  "final.endsOn": "Your 7-day free trial of Luminous StockHaven {planName} ends on {date}.",
  "final.endsSoon": "Your 7-day free trial of Luminous StockHaven {planName} ends within the next day.",
  "final.opening": "24 hours until your trial ends.",
