  "final.subject": "ನಿಮ್ಮ Luminous StockHaven ಪ್ರಯೋಗ ಮುಗಿಯಲು 24 ಗಂಟೆಗಳು ಬಾಕಿ ಇವೆ",
  "invite.aBusiness": "ಒಂದು ವ್ಯವಹಾರ",
