const baseOf = (language) => String(language || 'en').split('-')[0];

export function emailStringsFor(language) {
  const exact = EMAIL_STRINGS[language] || {};
  const base = EMAIL_STRINGS[baseOf(language)] || {};
  const out = {};
  for (const key of Object.keys(EMAIL_STRINGS.en)) {
    out[key] = exact[key] || base[key] || EMAIL_STRINGS.en[key];
  }
  return out;
}

export function fillEmail(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (match, name) =>
    values && values[name] != null ? String(values[name]) : match,
  );
}

export const EMAIL_STRING_KEYS = Object.keys(EMAIL_STRINGS.en);
export const EMAIL_STRING_LOCALES = Object.keys(EMAIL_STRINGS);
